import React from 'react';

export function OrbMain({ style = {} }) {
  return (
    <>
      {/* glow */}
      <div style={{
        position: 'absolute', left: '50%', transform: 'translateX(-50%)',
        width: 380, height: 380, top: 150,
        borderRadius: '50%', pointerEvents: 'none',
        background: 'radial-gradient(circle at 40% 40%, rgba(126,200,200,0.45) 0%, rgba(45,107,107,0.2) 50%, transparent 75%)',
        filter: 'blur(30px)',
        animation: 'orbFloat 10s ease-in-out infinite reverse',
        ...style,
      }} />
      {/* orb */}
      <div style={{
        position: 'absolute', left: '50%', transform: 'translateX(-50%)',
        width: 320, height: 320, top: 180,
        borderRadius: '50%', pointerEvents: 'none',
        background: 'radial-gradient(circle at 38% 35%, #7EC8C8 0%, #2D6B6B 45%, #1A3A3A 100%)',
        boxShadow: '0 0 120px rgba(45,107,107,0.35), 0 0 60px rgba(126,200,200,0.2)',
        animation: 'orbFloat 8s ease-in-out infinite',
      }} />
    </>
  );
}

export function OrbSmall({ style = {} }) {
  return (
    <div style={{
      width: 80, height: 80, borderRadius: '50%',
      background: 'radial-gradient(circle at 38% 35%, #7EC8C8, #2D6B6B)',
      boxShadow: '0 0 40px rgba(45,107,107,0.25)',
      animation: 'orbFloatFree 6s ease-in-out infinite',
      flexShrink: 0,
      ...style,
    }} />
  );
}
